place.example:
// client
const { Vector3 } = kcds.math;

const house = kcds.world.Prefab.place('house_1s_2r_a', new Vector3(120, 200, 10), new Vector3(0, 0, 90));
console.info(house.name);

place.exampleCs:
// client

var house = Prefab.Place("house_1s_2r_a", new Vector3(120, 200, 10), new Vector3(0, 0, 90));
Log.Info(house.Name);

find.example:
// client
for (const path of kcds.world.Prefab.find('living/houses', 10)) {
  console.info(path);
}

find.exampleCs:
// client
foreach (var path in Prefab.Find("living/houses", 10))
{
    Log.Info(path);
}

all.example:
// client
for (const prefab of kcds.world.Prefab.all()) {
  prefab.destroy();
}

all.exampleCs:
// client
foreach (var prefab in Prefab.All())
{
    prefab.Destroy();
}

